import { attr, button, emptyState, escapeHtml, formatTime, pageHeading } from '../helpers.js';
import { describeChange, pendingItems } from '../domain.js';

const e = escapeHtml;
const a = attr;
const textInput = (label, path, value, readonly, placeholder = '', { multiline = false, rows = 3 } = {}) => `<label class="field"><span>${e(label)}</span>${multiline ? `<textarea class="control textarea" rows="${rows}" name="${a(path)}" data-bind="${a(path)}" placeholder="${a(placeholder)}" ${readonly ? 'disabled' : ''}>${e(value ?? '')}</textarea>` : `<input class="control input" type="${['model.budget', 'handoff.resumeMinutes', 'materialPolicy.maxCount'].includes(path) ? 'number' : 'text'}" name="${a(path)}" data-bind="${a(path)}" value="${a(value ?? '')}" placeholder="${a(placeholder)}" ${readonly ? 'disabled' : ''}>`}</label>`;
const selectInput = (label, path, value, options, readonly) => `<label class="field"><span>${e(label)}</span><select class="control input" name="${a(path)}" data-bind="${a(path)}" ${readonly ? 'disabled' : ''}>${options.map(([key, text]) => `<option value="${a(key)}" ${key === value ? 'selected' : ''}>${e(text)}</option>`).join('')}</select></label>`;

export function renderBusiness({ agent, state, readonly }) {
  if (!agent) return emptyState('先选择专家', '业务办理属于具体专家的草稿。', button('navigate', '专家列表', { page: 'agents' }));
  const tools = agent.config.tools || [];
  const outcomes = [['handoff', '转人工'], ['later', '稍后回复'], ['refuse', '说明不能办理']];
  const cards = tools.map((tool, index) => {
    const prefix = `tools.${index}`;
    const stats = state.runs.filter(run => run.agentId === agent.id && run.toolId === tool.id && Date.parse(run.createdAt) >= Date.now() - 7 * 86400000 && Date.parse(run.createdAt) <= Date.now());
    const count = value => stats.filter(run => run.businessStatus === value).length;
    return `<article class="business-item"><header><h2>${e(tool.title)}</h2><span class="badge badge-neutral">${tool.mode === 'mock' ? '本地模拟 · 未接业务系统' : '连接状态待核验'}</span>${button('tool-remove', '移除办理', { id: tool.id, disabled: readonly, variant: 'ghost' })}</header><div class="business-fields">
      ${textInput('要问客户', `${prefix}.input`, tool.input || '', readonly, '例如：姓名、课程、时间段')}
      <label class="checkbox-field"><input type="checkbox" name="${prefix}.requiresConfirm" data-bind="${prefix}.requiresConfirm" ${tool.requiresConfirm ? 'checked' : ''} ${readonly || tool.sideEffect === 'write' ? 'disabled' : ''}><span>办之前需客户确认${tool.sideEffect === 'write' ? '（写入类必须开启）' : ''}</span></label>
      ${textInput('办成标志', `${prefix}.successField`, tool.successField || '', readonly, '例如：预约号')}
      ${selectInput('办不成时', `${prefix}.failureAction`, tool.failureAction || 'handoff', outcomes, readonly)}
      ${textInput('结果不明时', `${prefix}.unknownAction`, tool.unknownAction || '先查一次是否已经办成，不重复提交', readonly)}
    </div><footer><span>近 7 天：成功 ${count('success')} · 失败 ${count('failed')} · 结果不明 ${count('unknown')}</span><div class="button-group">${button('business-try', '试办一次', { id: tool.id, disabled: readonly })}${button('navigate', '看记录', { page: 'runs', variant: 'ghost' })}${button('evidence-open', '依据', { kind: 'tool', id: tool.id, variant: 'ghost' })}</div></footer>${state.ui.businessTryId === tool.id ? `<form data-form="business-try-run" class="business-try-form"><input type="hidden" name="id" value="${a(tool.id)}"><label>本地模拟结果<select class="control input" name="businessStatus" required><option value="">选择结果</option><option value="success">成功（仅脚本）</option><option value="failed">失败（仅脚本）</option><option value="unknown">结果不明（不重复提交）</option></select></label><button class="btn btn-primary" type="submit">记录这次模拟</button></form>` : ''}<details><summary>技术详情</summary><p>当前仅配置本地动作，不接收凭据或接口地址。正式执行需权限重验、预算、确认、幂等键与外部结果 ID。</p></details></article>`;
  }).join('');
  return `${pageHeading('业务办理', '', '')}${cards || emptyState('还没有业务办理', '可以先用知识库回答问题，确认需求后再接一项办理。')}<details class="add-section"><summary>接一项办理</summary><form class="stack compact-form" data-form="tool"><label class="field">办理名称<input class="control input" name="title" required placeholder="例如：创建试听预约"></label><label class="field">动作类型<select class="control input" name="sideEffect"><option value="read">只读查询</option><option value="write">业务写入（需客户确认）</option></select></label><label class="field">办成标志<input class="control input" name="successField" placeholder="例如：预约号"></label><button class="btn btn-primary" type="submit" ${readonly ? 'disabled' : ''}>登记办理</button></form></details>`;
}

export function renderSettings({ agent, readonly, state }) {
  const config = agent?.config;
  if (!config) return emptyState('先选择专家', '接待与回答设置属于具体专家。', button('navigate', '专家列表', { page: 'agents' }));
  return `${pageHeading('专家设置', '这些设置仅用于当前专家。', button('export-config', '导出草稿', { variant: 'ghost' }))}<div class="settings-links"><button data-action="navigate" data-page="configuration"><strong>更多设置</strong><span>收集信息与记录要求</span></button><button data-action="navigate" data-page="agents"><strong>返回工作区</strong><span>管理物料库、模型连接与部署</span></button></div><section class="settings-basics"><h2>接待与回答</h2><label class="field">专家名称<input class="control input" data-agent-name value="${a(agent.name)}" ${readonly ? 'disabled' : ''}></label>${textInput('服务目标', 'goal', config.goal, readonly, '', { multiline: true, rows: 3 })}${textInput('服务对象', 'audience', config.audience, readonly)}${textInput('回答范围', 'scope', config.scope, readonly, '', { multiline: true, rows: 3 })}${textInput('表达方式', 'tone', config.tone, readonly)}${textInput('欢迎语', 'greeting', config.greeting, readonly, '', { multiline: true, rows: 3 })}${textInput('资料不足时', 'fallback', config.fallback, readonly, '', { multiline: true, rows: 3 })}<details><summary>更多设置</summary>${textInput('单次模型预算', 'model.budget', config.model.budget, readonly)}${textInput('转人工接收方', 'handoff.recipient', config.handoff.recipient, readonly)}${textInput('恢复检查间隔（分钟）', 'handoff.resumeMinutes', config.handoff.resumeMinutes, readonly)}${textInput('每次最多发送物料数', 'materialPolicy.maxCount', config.materialPolicy?.maxCount, readonly)}${button('toggle-assistant', '创作助手（后续）', { variant: 'ghost' })}</details>${state?.ui.migrationBackupKey ? `<details><summary>迁移前副本</summary><p>旧本地记录已在首次保存前备份，包含原来的草稿和冻结版本。</p>${button('export-migration-backup', '导出迁移前副本')}</details>` : ''}</section>`;
}
export function renderTest({ agent, state, readonly }) {
  if (!agent) return emptyState('先选择专家', '测试题属于具体专家。', button('navigate', '专家列表', { page: 'agents' }));
  const tests = state.cases.filter(item => item.agentId === agent.id);
  const selected = tests.find(item => item.id === state.ui.testDetailId);
  const status = item => item.status !== 'reviewed' ? '待人工复核' : item.stale ? '待重新跑' : item.result === 'fail' ? '变差' : item.result === 'pass' ? '通过' : '待运行';
  const history = item => (item.history || []).slice(-5).map(entry => `<span title="${e(entry.result === 'pass' ? '通过' : '变差')}" aria-label="${e(entry.result === 'pass' ? '通过' : '变差')}">${entry.result === 'pass' ? '✓' : '×'}</span>`).join('') || '尚无记录';
  const detail = selected ? `<section class="test-detail"><div class="item-heading"><h2>${e(selected.title)}</h2>${button('test-back', '返回测试题', { variant: 'ghost' })}</div><dl class="definition-list"><div><dt>输入</dt><dd>${e(selected.input)}</dd></div><div><dt>期望</dt><dd>${e(selected.must || selected.expected || '待人工填写')}</dd></div><div><dt>这次答</dt><dd>${e(selected.lastObserved?.answer || '尚未运行')}</dd></div><div><dt>判定</dt><dd>${status(selected)}</dd></div></dl>${selected.result === 'fail' ? `<form data-form="case-decide" class="test-decision"><input type="hidden" name="id" value="${a(selected.id)}"><fieldset><legend>怎么处理</legend><label><input type="radio" name="decision" value="wrong" required>答案错了，上线时拦下</label><label><input type="radio" name="decision" value="outdated">测试题过时了，以这次为准并重新人工复核</label></fieldset><button class="btn btn-primary" type="submit" ${readonly ? 'disabled' : ''}>确定</button></form>` : ''}<div class="button-group">${button('case-edit', '编辑测试题', { id: selected.id, disabled: readonly })}${button('case-review', '人工复核', { id: selected.id, disabled: readonly || selected.status === 'reviewed' })}${button('case-evaluate', '跑这一题', { id: selected.id, disabled: readonly || selected.status !== 'reviewed' })}${selected.runId ? button('run-open', '看运行记录', { id: selected.runId, variant: 'ghost' }) : ''}</div><details><summary>最近 5 次</summary><p>${history(selected)}</p>${selected.truthHistory?.length ? `<p>真值修订 ${selected.truthHistory.length} 次，详情见本地记录。</p>` : ''}</details></section>` : '';
  const rows = tests.map(item => `<tr><td data-label="测试题"><button class="button-link" data-action="test-open" data-id="${a(item.id)}">${e(item.title)}</button><small>${e(item.input)}</small></td><td data-label="上次结果">${status(item)}</td><td data-label="最近 5 次" class="test-history">${history(item)}</td></tr>`).join('');
  const feedback = (state.feedback || []).filter(item => item.agentId === agent.id && item.status === 'open');
  return `${pageHeading('测试', '', `<div class="button-group">${button('case-create', '新建测试题', { disabled: readonly, variant: 'primary' })}${button('case-evaluate', '批量跑一次', { disabled: readonly })}</div>`)}${feedback.length ? `<section class="test-feedback"><h2>试一试发现的问题</h2>${feedback.map(item => `<p>${e(item.question)} ${button('feedback-to-case', '转为测试题', { id: item.id })}</p>`).join('')}</section>` : ''}<div class="table-wrap"><table class="data-table mobile-list test-table"><thead><tr><th>测试题</th><th>上次结果</th><th>最近 5 次</th></tr></thead><tbody>${rows}</tbody></table></div>${tests.length ? '' : emptyState('还没有测试题', '从试一试的答错反馈转为测试题，或手动新建。')}${detail}<div class="button-group test-links">${button('navigate', '看完整运行记录', { page: 'runs', variant: 'ghost' })}${button('navigate', '看改动候选', { page: 'iterations', variant: 'ghost' })}</div>`;
}

export function renderRelease({ agent, state, readonly }) {
  if (!agent) return emptyState('先选择专家', '上线版本属于具体专家。', button('navigate', '专家列表', { page: 'agents' }));
  const pending = pendingItems(agent, state), blocks = pending.filter(item => item.level === 'block');
  const live = agent.versions.find(item => item.id === agent.bindings.widget);
  const request = state.ui.releaseRequest?.agentId === agent.id && state.ui.releaseRequest?.revision === agent.revision ? state.ui.releaseRequest : null;
  const testVersion = agent.versions.find(item => item.id === agent.testVersionId && item.revision === agent.revision);
  const cases = state.cases.filter(item => item.agentId === agent.id);
  const regressed = cases.filter(item => item.result === 'fail');
  const changes = (agent.changeLog || []).filter(change => !live || change.revision > live.revision).slice(0, 5);
  return `${pageHeading('上线', '', '')}<div class="release-status"><span>线上：${live ? `${e(live.label || '已绑定版本')} · ${formatTime(live.createdAt)}` : '尚未上线'}</span><span>草稿：${state.ui.savedAt ? `${formatTime(state.ui.savedAt)} 已自动保存` : '正在自动保存'}</span></div>
    <section class="release-section"><h2>草稿相比线上改了什么</h2>${changes.length ? `<ul>${changes.map(change => `<li>${e(describeChange(change))} ${button('evidence-open', '依据', { kind: 'change', id: change.id, variant: 'ghost' })}</li>`).join('')}</ul>` : '<p class="muted">暂无新改动记录。</p>'}</section>
    <section class="release-section"><div class="item-heading"><h2>测试题</h2>${button('navigate', '看测试', { page: 'test' })}</div><p>${cases.length} 条里 ${cases.filter(item => item.result === 'pass').length} 条最近通过 · ${regressed.length} 条变差${regressed.length ? '，需先决定怎么处理' : ''}</p><p>测试环境：${testVersion ? '已接收当前草稿' : '尚未接收当前草稿'} · 接在：${agent.bindings.widget ? '网站小窗' : '未接网站小窗'}</p><div class="button-group">${button('navigate', '网站小窗', { page: 'widget', variant: 'ghost' })}${button('navigate', '联系页', { page: 'contact', variant: 'ghost' })}${button('navigate', '会话收件箱', { page: 'inbox', variant: 'ghost' })}</div></section>
    <section class="release-section release-readiness"><h2>能上线吗 · 待处理 ${pending.length}</h2>${pending.length ? `<ul>${pending.map(item => `<li><span>${item.level === 'block' ? '上线前必须处理' : '建议处理'} · ${e(item.text)}</span>${button('pending-open', item.fix, { id: item.id, variant: 'ghost' })}</li>`).join('')}</ul>` : '<p>当前草稿没有待处理项。</p>'}<div class="button-group release-actions">${button('sandbox-deploy', '发到测试环境', { disabled: readonly })}${button('release-request', '申请上线', { disabled: readonly || Boolean(blocks.length) || !testVersion, variant: 'primary' })}${button('release-rollback', '回到上一线上版', { disabled: readonly || (agent.liveBindingsHistory || []).length < 2, variant: 'ghost' })}</div>${request?.status === 'pending' ? `<div class="notice notice-warning"><p>上线申请等待人工确认；入口还没有改变。</p>${button('release-approve', '人工确认申请（本地）', { disabled: readonly })}</div>` : request?.status === 'approved' ? '<p class="notice">已记录本地人工确认；真实上线审批待服务端接入。</p>' : ''}</section>
    <details class="release-technical"><summary>技术详情</summary><p>当前草稿修订 r${e(agent.revision)}；线上版本 ${e(live?.id || '无')}；测试版本 ${e(testVersion?.id || '无')}。这些是当前浏览器中的快照和绑定，不是生产发布证据。</p><h2>全部冻结版本</h2>${agent.versions.map(version => `<p>${e(version.label || version.id)} · ${formatTime(version.createdAt)} ${button('version-preview', '只读查看', { id: version.id })}${button('version-restore', '恢复为新草稿', { id: version.id, disabled: readonly, variant: 'ghost' })}</p>`).join('')}<p>回到旧版本也会重新核验资料授权；已撤回的资料不会恢复使用。</p></details>`;
}
